1: // "Today" for the app, as an ISO date. Domain code never reads the clock itself:
2: // pages and routes call this once and pass the result in.
3: 
4: /** The calendar date of `now` in `timeZone` (Helsinki by default), as `YYYY-MM-DD`. */
5: export function todayIso(now: Date = new Date(), timeZone = 'Europe/Helsinki'): string {
6:   const parts = new Intl.DateTimeFormat('en-GB', {
7:     timeZone,
8:     year: 'numeric',
9:     month: '2-digit',
10:     day: '2-digit',
11:   }).formatToParts(now);
12:   const part = (type: Intl.DateTimeFormatPartTypes) =>
13:     parts.find((p) => p.type === type)?.value ?? '';
14:   return `${part('year')}-${part('month')}-${part('day')}`;
15: }

