1: // Worked example 2: which net list price applies to an asset on a given day.
2: import type { PriceList } from '@/data/schemas';
3: 
4: export type ListPriceResult =
5:   | { ok: true; priceCents: number; priceListVersion: number }
6:   | { ok: false; reason: 'unknown_asset' | 'no_price_list_on_date' };
7: 
8: const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;
9: 
10: /**
11:  * Returns the net list price (cents, VAT excluded) of `assetId` on `isoDate` (`YYYY-MM-DD`).
12:  * A price list applies from `valid_from` to `valid_to`, both days included;
13:  * `valid_to: null` means it has no end yet.
14:  *
15:  * The date is an argument on purpose: the caller decides what "today" is, so tests can
16:  * ask about any day and the answer never changes at midnight.
17:  */
18: export function listPriceOn(
19:   priceLists: readonly PriceList[],
20:   assetId: string,
21:   isoDate: string
22: ): ListPriceResult {
23:   if (!ISO_DATE.test(isoDate)) {
24:     throw new RangeError(`isoDate must look like YYYY-MM-DD, got "${isoDate}"`);
25:   }
26: 
27:   // ISO dates sort the same way as the days they name, so plain string comparison works.
28:   const priceList = priceLists.find(
29:     (list) => list.valid_from <= isoDate && (list.valid_to === null || isoDate <= list.valid_to)
30:   );
31:   if (!priceList) return { ok: false, reason: 'no_price_list_on_date' };
32: 
33:   const priceCents = priceList.prices[assetId];
34:   if (priceCents === undefined) return { ok: false, reason: 'unknown_asset' };
35: 
36:   return { ok: true, priceCents, priceListVersion: priceList.version };
37: }

