1: // Worked example 1: look up the monthly rent factor in the coefficient table.
2: // monthly net rent (cents) = financed amount (cents) × factor. Rounding is your decision.
3: import type { CoefficientBand, CoefficientTable } from '@/data/schemas';
4: 
5: export type MonthlyFactorResult =
6:   | { ok: true; band: CoefficientBand; factor: number }
7:   | { ok: false; reason: 'below_minimum' | 'above_maximum' | 'unknown_term' };
8: 
9: /**
10:  * Finds the band for `financedCents` and the factor for `termMonths` in that band.
11:  * Both band limits are inclusive: 199 999 cents is band A, 200 000 cents is band B.
12:  *
13:  * Returns a result instead of throwing, because "this amount cannot be financed" is a
14:  * normal business answer that the UI must show, not a bug.
15:  */
16: export function monthlyFactorFor(
17:   table: CoefficientTable,
18:   financedCents: number,
19:   termMonths: number
20: ): MonthlyFactorResult {
21:   if (!Number.isInteger(financedCents)) {
22:     // A non-integer here is a programming error: money is always whole cents.
23:     throw new RangeError(`financedCents must be whole cents, got ${financedCents}`);
24:   }
25: 
26:   const band = table.bands.find(
27:     (b) => financedCents >= b.min_financed_cents && financedCents <= b.max_financed_cents
28:   );
29:   if (!band) {
30:     const lowest = Math.min(...table.bands.map((b) => b.min_financed_cents));
31:     return { ok: false, reason: financedCents < lowest ? 'below_minimum' : 'above_maximum' };
32:   }
33: 
34:   const factor = band.monthly_factor_by_term[String(termMonths)];
35:   if (factor === undefined) return { ok: false, reason: 'unknown_term' };
36: 
37:   return { ok: true, band, factor };
38: }

