1: // Typed loaders for the read-only data pack in data/. Server-side only (they read files).
2: // Each loader reads one JSON file and checks it against its schema in ./schemas.ts,
3: // so a typo in the data fails loudly here instead of deep inside your pricing code.
4: import { readFile } from 'node:fs/promises';
5: import path from 'node:path';
6: import { z } from 'zod';
7: import {
8:   assetsFileSchema,
9:   co2FactorsSchema,
10:   coefficientTableSchema,
11:   customersFileSchema,
12:   priceListsFileSchema,
13:   questionsFileSchema,
14:   refurbishmentCostsSchema,
15:   residualCurvesSchema,
16:   secondLifeDemandFileSchema,
17:   vatRatesSchema,
18: } from './schemas';
19: 
20: /** The data pack folder: `data/` at the repository root. */
21: const DATA_DIR = path.join(process.cwd(), 'data');
22: 
23: /** Reads `data/<fileName>` and returns it parsed and validated. Throws if it does not match. */
24: export async function loadDataFile<S extends z.ZodType>(
25:   fileName: string,
26:   schema: S
27: ): Promise<z.output<S>> {
28:   const text = await readFile(path.join(DATA_DIR, fileName), 'utf8');
29:   const result = schema.safeParse(JSON.parse(text));
30:   if (!result.success) {
31:     throw new Error(
32:       `data/${fileName} does not match its schema:\n${z.prettifyError(result.error)}`
33:     );
34:   }
35:   return result.data;
36: }
37: 
38: export const loadAssets = () => loadDataFile('assets.json', assetsFileSchema);
39: export const loadPriceLists = () => loadDataFile('price-lists.json', priceListsFileSchema);
40: export const loadCoefficientTable = () =>
41:   loadDataFile('coefficient-table.json', coefficientTableSchema);
42: export const loadResidualCurves = () => loadDataFile('residual-curves.json', residualCurvesSchema);
43: export const loadVatRates = () => loadDataFile('vat-rates.json', vatRatesSchema);
44: export const loadQuestions = () => loadDataFile('questions.json', questionsFileSchema);
45: export const loadCustomers = () => loadDataFile('customers.json', customersFileSchema);
46: export const loadSecondLifeDemand = () =>
47:   loadDataFile('second-life-demand.json', secondLifeDemandFileSchema);
48: export const loadRefurbishmentCosts = () =>
