1: // One response shape for every API route:
2: //   { success: true,  data,  meta: { timestamp } }
3: //   { success: false, error: { code, message, details? }, meta: { timestamp } }
4: // Wrap each route handler in `handleRoute` so an unexpected error never leaks to the client.
5: import { ZodError, type z } from 'zod';
6: 
7: export type ApiMeta = { timestamp: string };
8: export type ApiErrorBody = { code: string; message: string; details?: unknown };
9: export type ApiSuccess<T> = { success: true; data: T; meta: ApiMeta };
10: export type ApiFailure = { success: false; error: ApiErrorBody; meta: ApiMeta };
11: export type ApiEnvelope<T> = ApiSuccess<T> | ApiFailure;
12: 
13: function meta(): ApiMeta {
14:   return { timestamp: new Date().toISOString() };
15: }
16: 
17: /** 200 (or `init.status`) with `{ success: true, data }`. */
18: export function ok<T>(data: T, init?: ResponseInit): Response {
19:   const body: ApiSuccess<T> = { success: true, data, meta: meta() };
20:   return Response.json(body, { status: 200, ...init });
21: }
22: 
23: /** An error response. `code` is a stable UPPER_SNAKE_CASE string clients can switch on. */
24: export function fail(status: number, code: string, message: string, details?: unknown): Response {
25:   const error: ApiErrorBody =
26:     details === undefined ? { code, message } : { code, message, details };
27:   const body: ApiFailure = { success: false, error, meta: meta() };
28:   return Response.json(body, { status });
29: }
30: 
31: /** Throw this anywhere inside a handler to answer with a specific error. */
32: export class ApiError extends Error {
33:   readonly status: number;
34:   readonly code: string;
35:   readonly details?: unknown;
36: 
37:   constructor(status: number, code: string, message: string, details?: unknown) {
38:     super(message);
39:     this.name = 'ApiError';
40:     this.status = status;
41:     this.code = code;
42:     this.details = details;
43:   }
44: }
45: 
46: /** Turns anything a handler threw into a safe response. Unknown errors become a generic 500. */
47: export function errorToResponse(error: unknown): Response {
48:   if (error instanceof ApiError) {
49:     return fail(error.status, error.code, error.message, error.details);
50:   }
51:   if (error instanceof ZodError) {
52:     const issues = error.issues.map((issue) => ({
53:       path: issue.path.map(String).join('.'),
54:       message: issue.message,
55:       code: issue.code,
56:     }));
57:     return fail(400, 'VALIDATION_ERROR', 'The request is not valid', issues);
58:   }
59:   // The real error goes to the server log only. The client never sees its message,
60:   // because it can contain SQL, file paths or personal data.
61:   console.error('Unhandled error in route handler:', error);
62:   return fail(500, 'INTERNAL_ERROR', 'Something went wrong');
63: }
64: 
65: /**
66:  * Wraps a route handler so thrown errors become envelope responses.
67:  *
68:  *   export const GET = handleRoute(async (request) => ok(await listThings()));
69:  */
70: export function handleRoute<Context = unknown>(
71:   handler: (request: Request, context: Context) => Promise<Response>
72: ): (request: Request, context: Context) => Promise<Response> {
73:   return async (request, context) => {
74:     try {
75:       return await handler(request, context);
76:     } catch (error) {
77:       return errorToResponse(error);
78:     }
79:   };
80: }
81: 
82: /** Reads a JSON body and validates it. Bad JSON → 400 INVALID_JSON; wrong shape → 400 VALIDATION_ERROR. */
83: export async function readJsonBody<S extends z.ZodType>(
84:   request: Request,
85:   schema: S
86: ): Promise<z.output<S>> {
87:   let body: unknown;
88:   try {
89:     body = await request.json();
90:   } catch {
91:     throw new ApiError(400, 'INVALID_JSON', 'The request body must be valid JSON');
92:   }
93:   return schema.parse(body);
94: }

