1: // Audit trail: every change to business data writes an AuditLog row in the SAME database
2: // transaction as the change. If either write fails, both are rolled back, so the database
3: // can never hold a change that nobody can explain.
4: import type { Prisma, PrismaClient } from '@/generated/prisma/client';
5: 
6: export type AuditEntry = {
7:   /** Who did it (a user id or name; there is no login in the starter). */
8:   actor: string;
9:   /** What happened, as `<entity>.<verb>`, e.g. `asset.status_changed`. */
10:   action: string;
11:   entityType: string;
12:   entityId: string;
13:   /** Anything useful for a later reader, e.g. `{ from: 'available', to: 'reserved' }`. Stored as JSON. */
14:   details?: unknown;
15: };
16: 
17: export type TransactionClient = Prisma.TransactionClient;
18: 
19: /**
20:  * Runs `work` inside a transaction and records `entry` in the audit log.
21:  * Use the `tx` you are given for every write in `work`; writes through `db` would
22:  * escape the transaction.
23:  *
24:  *   const asset = await withAudit(db, { actor, action: 'asset.status_changed', ... },
25:  *     (tx) => tx.asset.update({ where: { id }, data: { status } }));
26:  */
27: export async function withAudit<T>(
28:   db: PrismaClient,
29:   entry: AuditEntry,
30:   work: (tx: TransactionClient) => Promise<T>
31: ): Promise<T> {
32:   return db.$transaction(async (tx) => {
33:     const result = await work(tx);
34:     await tx.auditLog.create({
35:       data: {
36:         actor: entry.actor,
37:         action: entry.action,
38:         entity_type: entry.entityType,
39:         entity_id: entry.entityId,
40:         details_json: entry.details === undefined ? null : JSON.stringify(entry.details),
41:       },
42:     });
43:     return result;
44:   });
45: }
46: 
47: export type AuditLogEntry = {
48:   id: number;
49:   created_at: string;
50:   actor: string;
51:   action: string;
52:   entity_type: string;
53:   entity_id: string;
54:   details: unknown;
55: };
56: 
57: /** The newest audit rows first. */
58: export async function listAuditLog(db: PrismaClient, limit = 50): Promise<AuditLogEntry[]> {
59:   const rows = await db.auditLog.findMany({
60:     orderBy: [{ created_at: 'desc' }, { id: 'desc' }],
61:     take: limit,
62:   });
63:   return rows.map((row) => ({
64:     id: row.id,
65:     created_at: row.created_at.toISOString(),
66:     actor: row.actor,
67:     action: row.action,
68:     entity_type: row.entity_type,
69:     entity_id: row.entity_id,
70:     details: row.details_json === null ? null : JSON.parse(row.details_json),
71:   }));
72: }

