52:   { ok: true; asset: Asset } | { ok: false; reason: 'not_found' };
53: 
54: /** Sets an asset's status and writes `asset.status_changed` to the audit log, atomically. */
55: export async function changeAssetStatus(
56:   db: PrismaClient,
57:   input: { id: string; status: AssetStatus; actor: string }
58: ): Promise<ChangeAssetStatusResult> {
59:   const existing = await db.asset.findUnique({ where: { id: input.id } });
60:   if (!existing) return { ok: false, reason: 'not_found' };
61: 
62:   const updated = await withAudit(
63:     db,
64:     {
65:       actor: input.actor,
66:       action: 'asset.status_changed',
67:       entityType: 'asset',
68:       entityId: input.id,
69:       details: { from: existing.status, to: input.status },
70:     },
71:     (tx) => tx.asset.update({ where: { id: input.id }, data: { status: input.status } })
72:   );
73:   return { ok: true, asset: toAsset(updated) };
74: }
75: 
76: /** Inserts assets that are not in the database yet. Never overwrites changes you made. */
77: export async function seedAssets(
78:   db: PrismaClient,
79:   assets: readonly Asset[]
80: ): Promise<{ created: number; skipped: number }> {
81:   const existing = await db.asset.findMany({ select: { id: true } });
82:   const existingIds = new Set(existing.map((row) => row.id));
83:   const missing = assets.filter((asset) => !existingIds.has(asset.id));
84:   if (missing.length > 0) {
85:     await db.asset.createMany({ data: missing.map(toAssetRowData) });
86:   }
87:   return { created: missing.length, skipped: assets.length - missing.length };
88: }

