1: // Fails when a hand-written source file is longer than 600 lines.
2: // Long files are hard to review in a pull request: split by responsibility instead.
3: // Usage: node scripts/check-file-size.mjs
4: import { execFileSync } from 'node:child_process';
5: import { readFileSync } from 'node:fs';
6: import { pathToFileURL } from 'node:url';
7: 
8: export const MAX_LINES = 600;
9: 
10: const SOURCE_EXTENSIONS = /\.(ts|tsx|js|jsx|mjs|cjs)$/;
11: 
12: /** Paths that are generated, vendored or tests: not counted. */
13: const EXCLUDED = [
14:   /(^|\/)node_modules\//,
15:   /(^|\/)\.next\//,
16:   /(^|\/)coverage\//,
17:   /(^|\/)generated\//,
18:   /^prisma\/migrations\//,
19:   /\.(test|spec)\.[cm]?[jt]sx?$/,
20:   /(^|\/)next-env\.d\.ts$/,
21: ];
22: 
23: /** True when `path` (relative, forward slashes) is a source file we measure. */
24: export function isCheckedFile(path) {
25:   return SOURCE_EXTENSIONS.test(path) && !EXCLUDED.some((pattern) => pattern.test(path));
26: }
27: 
28: /** Number of lines in `text`; a final newline does not start a new line. */
29: export function countLines(text) {
30:   if (text === '') return 0;
31:   const lines = text.split('\n').length;
32:   return text.endsWith('\n') ? lines - 1 : lines;
33: }
34: 
35: /**
36:  * @param {string[]} paths candidate files
37:  * @param {(path: string) => string | null} read returns file text, or null if it is gone
38:  * @returns {{ path: string, lines: number }[]} files over the limit
39:  */
40: export function findOversizedFiles(paths, read, maxLines = MAX_LINES) {
41:   const oversized = [];
42:   for (const path of paths.filter(isCheckedFile)) {
43:     const text = read(path);
44:     if (text === null) continue;
45:     const lines = countLines(text);
46:     if (lines > maxLines) oversized.push({ path, lines });
47:   }
48:   return oversized;
49: }
50: 
51: /** Tracked files plus untracked files that are not ignored. */
52: function listRepositoryFiles() {
53:   const output = execFileSync(
54:     'git',
55:     ['ls-files', '-z', '--cached', '--others', '--exclude-standard'],
56:     {
57:       encoding: 'utf8',
58:     }
59:   );
60:   return [...new Set(output.split('\0').filter(Boolean))];
61: }
62: 
63: function readIfExists(path) {
64:   try {
65:     return readFileSync(path, 'utf8');
66:   } catch (error) {
67:     if (error.code === 'ENOENT') return null; // deleted but still in the index
68:     throw error;
69:   }
70: }
71: 
72: function main() {
73:   const oversized = findOversizedFiles(listRepositoryFiles(), readIfExists);
74:   if (oversized.length === 0) {
75:     console.log(`✅ No source file is over ${MAX_LINES} lines.`);
76:     return;
77:   }
78:   console.error(`❌ These files are over ${MAX_LINES} lines. Split them into smaller modules:\n`);
79:   for (const { path, lines } of oversized) console.error(`  ${path}: ${lines} lines`);
80:   process.exitCode = 1;
81: }
